// The dish-kinds catalog (kinds.json, generated by scripts/kinds/gen-kinds.js; docs/kinds-catalog.md is its review copy) and
// the shapes a meal is stored in: a slot's kinds and templates. A kind is a dish family (Idli, Dosa, Sabzi, Dal), with sub-kinds
// named the way families say them (Poriyal, Pappu, Sambar) and items, its variants. A template is one way a meal is plated:
// [Roti, Sabzi], [Rice, Sambar, Rasam, Poriyal], [Appam, Vegetable stew]. Decided rules: scripts/kinds/decided.md.
import catalogJson from "./kinds.json";
import { FREQUENCY_WORDS, type Frequency } from "./db/constants";

// ── The catalog ──

export type CatalogItem = { name: string; aka?: string[]; cuisines?: string[]; contains: string[]; suggest: boolean; regional?: boolean;
  sub: string; diet?: string; meals?: string[] };
export type CatalogSub = { name: string; aka: string[]; cuisines: string[]; meals: string[] };
export type CatalogKind = { name: string; aka: string[]; cuisines: string[]; meals: string[]; staple: boolean; part: string; diet: string;
  subs: CatalogSub[]; items: CatalogItem[] };
export type Catalog = { version: number; tags: string[]; parents: Record<string, string>; kinds: CatalogKind[]; notes?: string[] };

export const CATALOG = catalogJson as Catalog;

/** A dish's words as the catalog is matched on: lowercase, letters and digits, single spaces. */
export const norm = (s: string): string => s.toLowerCase().normalize("NFKD").replace(/[̀-ͯ]/g, "").replace(/[^a-z0-9]+/g, " ").trim();
/** The word and its singular ("idlis" → "idli", "pakoras" → "pakora"); matching tries both. */
const forms = (s: string): string[] => { const n = norm(s); return n.endsWith("s") && n.length > 3 ? [n, n.slice(0, -1)] : [n]; };
/** A sub-kind's names: "Poriyal/Thoran" is said as either. */
const subNames = (sb: CatalogSub): string[] => [...sb.name.split("/"), sb.name, ...sb.aka];

/** Where a family's words land in the catalog: the item when they named one, else the sub-kind or kind. `by` says what matched. */
export type DishMatch = { kind: string; sub: string | null; item: string | null; by: "item" | "sub" | "kind" };

type Index = { items: Map<string, DishMatch[]>; subs: Map<string, DishMatch[]>; kinds: Map<string, DishMatch[]> };
let index: Index | null = null;
function buildIndex(c: Catalog): Index {
  const ix: Index = { items: new Map(), subs: new Map(), kinds: new Map() };
  const add = (m: Map<string, DishMatch[]>, word: string, hit: DishMatch) => {
    const k = norm(word);
    if (!k) return;
    const list = m.get(k) ?? [];
    if (!list.some((h) => h.kind === hit.kind && h.sub === hit.sub && h.item === hit.item)) list.push(hit);
    m.set(k, list);
  };
  for (const k of c.kinds) {
    for (const w of [k.name, ...k.aka]) add(ix.kinds, w, { kind: k.name, sub: null, item: null, by: "kind" });
    // A kind of one sub-kind has no sub-kind of its own to name.
    if (k.subs.length > 1) for (const sb of k.subs) for (const w of subNames(sb)) add(ix.subs, w, { kind: k.name, sub: sb.name, item: null, by: "sub" });
    for (const it of k.items) for (const w of [it.name, ...(it.aka ?? [])]) add(ix.items, w, { kind: k.name, sub: it.sub, item: it.name, by: "item" });
  }
  return ix;
}
const ix = (): Index => (index ??= buildIndex(CATALOG));

/** Match a family's words for a dish ("aloo gobi", "poriyal", "idlis") to the catalog: an item first, then a sub-kind, then a
 *  kind, each by its name or other names, as said or as a singular. Null when nothing matches, or when the words name more than
 *  one place at the level that matched ("shaak" is both a dry and a gravy vegetable): those are left to the model. */
export function matchDish(words: string): DishMatch | null {
  for (const level of ["items", "subs", "kinds"] as const) {
    for (const f of forms(words)) {
      const hits = ix()[level].get(f);
      if (!hits?.length) continue;
      if (hits.length > 1) {
        // One item listed under one kind twice over is still one place; anything else is for the model to settle.
        const places = new Set(hits.map((h) => `${h.kind}|${h.sub ?? ""}|${level === "items" ? h.item : ""}`));
        return places.size === 1 ? hits[0] : null;
      }
      return hits[0];
    }
  }
  return null;
}

export const catalogKind = (name: string): CatalogKind | null => CATALOG.kinds.find((k) => norm(k.name) === norm(name)) ?? null;
export const catalogItem = (name: string): { kind: CatalogKind; item: CatalogItem } | null => {
  for (const kind of CATALOG.kinds) { const item = kind.items.find((i) => norm(i.name) === norm(name)); if (item) return { kind, item }; }
  return null;
};

/** The meals a NEW item of this kind, sub-kind or item may be suggested at (decided 18). They never limit a family's own dish. */
export function suggestMeals(m: { kind: string; sub?: string | null; item?: string | null }): string[] {
  const k = catalogKind(m.kind);
  if (!k) return [];
  const it = m.item ? k.items.find((i) => norm(i.name) === norm(m.item!)) : null;
  if (it?.meals) return it.meals;
  const subName = it?.sub ?? m.sub;
  const sb = subName ? k.subs.find((s) => norm(s.name) === norm(subName)) : null;
  return sb?.meals ?? k.meals;
}

/** What an item contains, with each tag's family added (chicken → meat, prawn → seafood). Null for a dish not in the catalog. */
export function catalogContains(itemName: string): string[] | null {
  const hit = catalogItem(itemName);
  if (!hit) return null;
  const out = new Set(hit.item.contains);
  for (const t of hit.item.contains) for (let p = CATALOG.parents[t]; p; p = CATALOG.parents[p]) out.add(p);
  return [...out];
}

/** The items the planner may suggest as new for a kind (or one of its sub-kinds) to a family of these cuisines: `suggest` items,
 *  and a regional one only when one of its cuisines is the family's (decided 7). Staple kinds give none. */
export function suggestable(kind: string, opts: { sub?: string | null; cuisines?: readonly string[] } = {}): CatalogItem[] {
  const k = catalogKind(kind);
  if (!k || k.staple) return [];
  const fam = new Set((opts.cuisines ?? []).map(norm));
  return k.items.filter((it) => it.suggest && (!opts.sub || norm(it.sub) === norm(opts.sub))
    && (!it.regional || (it.cuisines ?? []).some((c) => fam.has(norm(c)))));
}

// ── A meal's shape, stored on its slot ──

/** One kind a slot's meals are built from. `subs`: the family's own sub-kinds of it (rotation prefers them; another sub-kind's
 *  item is a new variant). `staple`: comes every day its template has it, never rotated (roti, rice, curd). `own`: a kind only
 *  this family has (a dish with no kind in the catalog): nothing new is ever suggested for it. */
export type MealKind = { name: string; subs?: string[]; staple?: boolean; own?: boolean };
/** One part of a template: a kind or one sub-kind of it (filled from the family's items of it, then new ones), or a fixed list
 *  of the family's own dishes (nothing new suggested: a dish they named at a meal outside the catalog's meals for it, decided
 *  18 and 19). */
export type TemplatePart = { kind: string; sub?: string } | { items: string[] };
/** One way the meal is plated. `share`: how often, in the family's words' measure ("2/week", "usually"); null = spread evenly
 *  with the others. `said`: those words ("poha twice a week"). */
export type MealTemplate = { parts: TemplatePart[]; share?: Frequency | null; said?: string | null };

const isFrequency = (v: unknown): v is Frequency =>
  typeof v === "string" && ((FREQUENCY_WORDS as readonly string[]).includes(v) || /^[1-7]\/week$/.test(v));

/** What is wrong with a slot's kinds and templates, one line each; empty when they are fine. A catalog kind is named as the
 *  catalog names it (any capitals); a sub-kind must be one of its kind's; an own kind must not be a catalog kind; every kind a
 *  template names must be among the slot's kinds. */
export function checkMealShape(kinds: readonly MealKind[], templates: readonly MealTemplate[]): string[] {
  const errs: string[] = [];
  const seen = new Map<string, MealKind>();
  for (const k of kinds) {
    if (!k?.name?.trim()) { errs.push("a kind has no name"); continue; }
    if (seen.has(norm(k.name))) errs.push(`${k.name}: named twice`);
    seen.set(norm(k.name), k);
    const cat = catalogKind(k.name);
    if (k.own) {
      if (cat) errs.push(`${k.name}: is a catalog kind, not an own one`);
      if (k.subs?.length) errs.push(`${k.name}: an own kind has no sub-kinds`);
      continue;
    }
    if (!cat) { errs.push(`${k.name}: not a catalog kind (mark it own if only this family has it)`); continue; }
    for (const s of k.subs ?? []) if (!cat.subs.some((x) => norm(x.name) === norm(s))) errs.push(`${k.name}: ${s} is not one of its sub-kinds (${cat.subs.map((x) => x.name).join(", ")})`);
  }
  templates.forEach((t, i) => {
    const at = `template ${i + 1}`;
    if (!t?.parts?.length) { errs.push(`${at}: has no parts`); return; }
    if (t.share != null && !isFrequency(t.share)) errs.push(`${at}: share ${String(t.share)} is not usually, sometimes, rarely, daily or "<n>/week"`);
    for (const p of t.parts) {
      if ("items" in p) {
        if (!Array.isArray(p.items) || !p.items.length || p.items.some((x) => typeof x !== "string" || !x.trim())) errs.push(`${at}: a part of items needs their dishes' names`);
        continue;
      }
      const k = seen.get(norm(p.kind ?? ""));
      if (!k) { errs.push(`${at}: ${p.kind} is not one of this meal's kinds`); continue; }
      if (p.sub) {
        const cat = k.own ? null : catalogKind(k.name);
        if (!cat || !cat.subs.some((x) => norm(x.name) === norm(p.sub!))) errs.push(`${at}: ${p.sub} is not a sub-kind of ${k.name}`);
      }
    }
  });
  return errs;
}
